<?php
require_once __DIR__.'/layout.php';$admin=require_role(['admin']);$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{
 if($a==='year'){$name=trim($_POST['name']);$active=isset($_POST['active'])?1:0;if($active)$pdo->exec('UPDATE academic_years SET active=0');$pdo->prepare('INSERT INTO academic_years(name,active) VALUES(?,?)')->execute([$name,$active]);}
 if($a==='section'){$pdo->prepare('INSERT INTO sections(academic_year_id,grade_name,section_name,technical_track,professional_family) VALUES(?,?,?,?,?)')->execute([(int)$_POST['academic_year_id'],trim($_POST['grade_name']),trim($_POST['section_name']),trim($_POST['technical_track'])?:null,trim($_POST['professional_family'])?:null]);}
 if($a==='subject'){$pdo->prepare('INSERT INTO subjects(code,name,type) VALUES(?,?,?)')->execute([trim($_POST['code'])?:null,trim($_POST['name']),$_POST['type']]);}
 if($a==='assign'){$pdo->prepare('INSERT IGNORE INTO teacher_assignments(user_id,section_id,subject_id) VALUES(?,?,?)')->execute([(int)$_POST['user_id'],(int)$_POST['section_id'],(int)$_POST['subject_id']]);}
 if($a==='ra'){$pdo->prepare('INSERT INTO learning_results(subject_id,ra_code,title,sort_order) VALUES(?,?,?,?)')->execute([(int)$_POST['subject_id'],trim($_POST['ra_code']),trim($_POST['title']), (int)($_POST['sort_order']??0)]);}
 flash('success','Configuración guardada.');
 }catch(Throwable $e){flash('error','No se pudo guardar. Verifique si el registro ya existe.');}header('Location: catalogs.php');exit;}
$years=$pdo->query('SELECT * FROM academic_years ORDER BY active DESC,name DESC')->fetchAll();$sections=$pdo->query("SELECT se.*,ay.name year_name FROM sections se JOIN academic_years ay ON ay.id=se.academic_year_id ORDER BY ay.active DESC,se.grade_name,se.section_name")->fetchAll();$subjects=$pdo->query('SELECT * FROM subjects WHERE active=1 ORDER BY type,name')->fetchAll();$teachers=$pdo->query("SELECT id,full_name FROM users WHERE role='teacher' AND active=1 ORDER BY full_name")->fetchAll();$assign=$pdo->query("SELECT ta.id,u.full_name,CONCAT(se.grade_name,' ',se.section_name) section_label,su.name subject_name FROM teacher_assignments ta JOIN users u ON u.id=ta.user_id JOIN sections se ON se.id=ta.section_id JOIN subjects su ON su.id=ta.subject_id ORDER BY u.full_name,se.grade_name,se.section_name,su.name")->fetchAll();
app_header('Configuración académica'); ?>
<div class="sys-grid"><div class="panel"><h2>Año escolar</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="year"><label>Nombre<input name="name" placeholder="2026-2027" required></label><label style="margin-top:.7rem"><input type="checkbox" name="active" value="1" style="width:auto;display:inline"> Marcar como activo</label><button class="button">Agregar</button></form></div><div class="panel"><h2>Sección</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="section"><label>Año<select name="academic_year_id" required><?php foreach($years as $y):?><option value="<?=$y['id']?>"><?=h($y['name'])?></option><?php endforeach;?></select></label><div class="form-grid"><label class="c6">Grado<input name="grade_name" placeholder="4to" required></label><label class="c6">Sección<input name="section_name" placeholder="B" required></label><label class="c6">Bachiller técnico<input name="technical_track"></label><label class="c6">Familia profesional<input name="professional_family"></label></div><button class="button">Agregar</button></form></div><div class="panel"><h2>Asignatura / módulo</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="subject"><label>Código<input name="code"></label><label>Nombre<input name="name" required></label><label>Tipo<select name="type"><option value="curricular">Área curricular</option><option value="technical">Módulo formativo</option></select></label><button class="button">Agregar</button></form></div><div class="panel"><h2>Asignar docente</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="assign"><label>Docente<select name="user_id" required><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=h($t['full_name'])?></option><?php endforeach;?></select></label><label>Sección<select name="section_id" required><?php foreach($sections as $s):?><option value="<?=$s['id']?>"><?=h($s['grade_name'].' '.$s['section_name'].' · '.$s['year_name'])?></option><?php endforeach;?></select></label><label>Asignatura<select name="subject_id" required><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=h($s['name'])?></option><?php endforeach;?></select></label><button class="button">Asignar</button></form></div></div>
<div class="panel"><h2>Resultados de aprendizaje (RA)</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="ra"><div class="form-grid"><label class="c4">Módulo<select name="subject_id" required><?php foreach($subjects as $s):if($s['type']!=='technical')continue;?><option value="<?=$s['id']?>"><?=h($s['name'])?></option><?php endforeach;?></select></label><label class="c2">Código<input name="ra_code" placeholder="RA1" required></label><label class="c4">Descripción<input name="title" required></label><label class="c2">Orden<input type="number" name="sort_order" value="1"></label></div><button class="button">Agregar RA</button></form></div>
<div class="panel"><h2>Asignaciones docentes</h2><div class="table-wrap"><table class="sys-table"><thead><tr><th>Docente</th><th>Sección</th><th>Asignatura</th></tr></thead><tbody><?php foreach($assign as $a):?><tr><td><?=h($a['full_name'])?></td><td><?=h($a['section_label'])?></td><td><?=h($a['subject_name'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php app_footer(); ?>
